package org.example.comment;

import jakarta.validation.Valid;
import org.example.auth.AuthenticatedMember;
import org.example.auth.LoginMember;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.net.URI;
import java.util.List;

@RestController
public class CommentController {
    private final MyBatisCommentService comments;
    private final MyBatisCommentQueryService query;

    public CommentController(MyBatisCommentService comments, MyBatisCommentQueryService query) {
        this.comments = comments;
        this.query = query;
    }

    @PostMapping("/api/posts/{postId}/comments")
    public ResponseEntity<CommentResponse> create(@PathVariable Long postId,
            @LoginMember AuthenticatedMember member, @Valid @RequestBody CommentCreateRequest request) {
        CommentResponse created = comments.create(postId, member, request);
        return ResponseEntity.created(URI.create("/api/comments/" + created.id())).body(created);
    }

    @GetMapping("/api/posts/{postId}/comments")
    public List<CommentThreadResponse> list(@PathVariable Long postId,
            @LoginMember AuthenticatedMember viewer) {
        return query.list(postId, viewer);
    }

    @DeleteMapping("/api/comments/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void delete(@PathVariable Long id, @LoginMember AuthenticatedMember member) {
        comments.delete(id, member);
    }
}

