package org.example.notification;

import org.example.auth.AuthenticatedMember;
import org.example.post.AuthorResponse;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

import java.time.Clock;
import java.time.LocalDateTime;
import java.util.List;

@Service
public class NotificationService {

    private final MyBatisNotificationMapper notifications;
    private final Clock clock;

    public NotificationService(MyBatisNotificationMapper notifications, Clock clock) {
        this.notifications = notifications;
        this.clock = clock;
    }

    // 좋아요·댓글의 기존 트랜잭션이 있어야 한다. Mapper 예외는 그대로 전파해 원래 작업도 롤백한다.
    @Transactional(propagation = Propagation.MANDATORY)
    public void notifyLike(Long postId, Long actorId) {
        create(postId, actorId, Notification.LIKE, null);
    }

    @Transactional(propagation = Propagation.MANDATORY)
    public void notifyComment(Long postId, Long commentId, Long actorId) {
        create(postId, actorId, Notification.COMMENT, commentId);
    }

    private void create(Long postId, Long actorId, String type, Long commentId) {
        Long receiverId = notifications.findReceiverId(postId);
        if (receiverId == null || receiverId.equals(actorId)) return;
        if (notifications.insert(receiverId, actorId, type, postId, commentId,
                LocalDateTime.now(clock)) != 1) {
            throw new IllegalStateException("알림 저장 실패");
        }
    }

    @Transactional(readOnly = true)
    public NotificationListResponse list(AuthenticatedMember me, boolean unreadOnly, int size) {
        List<NotificationResponse> items = notifications.findMine(me.id(), unreadOnly, size).stream()
                .map(row -> new NotificationResponse(row.id, row.type,
                        new AuthorResponse(row.actorId, row.actorNickname),
                        row.postId, row.commentId, row.readAt != null, row.createdAt))
                .toList();
        return new NotificationListResponse(items, notifications.countUnread(me.id()));
    }

    @Transactional
    public void markRead(AuthenticatedMember me, Long notificationId) {
        if (notifications.findOwnedId(notificationId, me.id()) == null) {
            throw new NotificationNotFoundException();
        }
        notifications.markRead(notificationId, me.id(), LocalDateTime.now(clock));
    }
}

