// 행과 연관 데이터를 지우지 않고 삭제 시각만 기록한다.
@Service
public class PostDeleteMyBatisService {
    private final PostVisibilityMapper visibilityMapper;
    private final PostReplaceMapper replaceMapper;

    public PostDeleteMyBatisService(PostVisibilityMapper visibilityMapper,
                                    PostReplaceMapper replaceMapper) {
        this.visibilityMapper = visibilityMapper;
        this.replaceMapper = replaceMapper;
    }

    @Transactional
    public void delete(Long id, AuthenticatedMember me) {
        PostDetailRow current = visibilityMapper.findVisibleDetail(id, me.id(), me.role());
        if (current == null) throw new PostNotFoundException();
        if (!current.authorId.equals(me.id()) && !"ADMIN".equals(me.role()))
            throw new PostForbiddenException();
        if (replaceMapper.softDelete(id) != 1) throw new PostNotFoundException();
    }
}

