package org.example.post;

import org.example.auth.AuthenticatedMember;
import org.example.board.BoardNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.util.Map;
import java.util.stream.Collectors;

// 글 조회 전용 서비스 — 1-3/1-4의 PostService(쓰기)와 책임을 나눈다
@Service
public class PostQueryService {

    private final PostVisibilityMapper mapper;

    public PostQueryService(PostVisibilityMapper mapper) {
        this.mapper = mapper;
    }


    @Transactional(readOnly = true)
    public List<PostHeadlineResponse> listPublicByAuthor(Long memberId, String boardSlug) {
        if (boardSlug == null || boardSlug.isBlank()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "게시판을 선택해 주세요.");
        }
        if (mapper.findMemberId(memberId) == null) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "회원을 찾을 수 없습니다.");
        }
        if (mapper.findBoardIdBySlug(boardSlug) == null) {
            throw new BoardNotFoundException(boardSlug);
        }
        return mapper.selectPublicByAuthorAndBoard(memberId, boardSlug).stream()
                .map(row -> new PostHeadlineResponse(row.id, row.title,
                        row.authorNickname, row.boardSlug)).toList();
    }

    @Transactional
    public PostDetailResponse getDetail(Long id, AuthenticatedMember viewer) {
        Long viewerId = viewer == null ? null : viewer.id();
        String viewerRole = viewer == null ? null : viewer.role();
        // SQL에서 권한을 먼저 걸러 404일 때 조회수가 변하지 않게 한다.
        PostDetailRow row = mapper.findVisibleDetail(id, viewerId, viewerRole);
        if (row == null) {
            throw new PostNotFoundException();
        }
        mapper.increaseViewCount(id);
        List<String> tags = mapper.findTagsByPostIds(List.of(id)).stream()
                .map(PostTagRow::name).toList();
        return new PostDetailResponse(row.id, row.boardSlug, row.title, row.content,
                tags, row.visibility, new AuthorResponse(row.authorId, row.authorNickname),
                row.viewCount + 1, row.likeCount, row.commentCount, row.createdAt);
    }

    @Transactional(readOnly = true)
    public PostListResponse list(String boardSlug, int page, int size, AuthenticatedMember viewer) {
        Long boardId = mapper.findBoardIdBySlug(boardSlug);
        if (boardId == null) throw new BoardNotFoundException(boardSlug);

        Long viewerId = viewer == null ? null : viewer.id();

        long offset = (long) page * size;
        List<PostListRow> rows = mapper.findViewableByBoard(boardId, viewerId, size, offset);
        long total = mapper.countViewableByBoard(boardId, viewerId);
        Map<Long, List<String>> tags = rows.isEmpty() ? Map.of()
                : mapper.findTagsByPostIds(rows.stream().map(row -> row.id).toList()).stream()
                    .collect(Collectors.groupingBy(PostTagRow::postId,
                            Collectors.mapping(PostTagRow::name, Collectors.toList())));
        List<PostListItemResponse> items = rows.stream()
                .map(row -> toListItem(row, tags.getOrDefault(row.id, List.of()))).toList();

        return new PostListResponse(
                items,
                page,
                size,
                total,
                (int) ((total + size - 1) / size),
                offset + rows.size() < total
        );
    }

    // 8-4 조합 검색 — SQL에서 조회 가능 조건과 선택 필터를 모두 적용한다.
    @Transactional(readOnly = true)
    public PostListResponse search(String boardSlug, String tag, Long authorId, LocalDate from, LocalDate to,
                                   String q, int page, int size, AuthenticatedMember viewer) {
        if (from != null && to != null && from.isAfter(to)) {
            throw new InvalidSearchConditionException("from이 to보다 늦을 수 없습니다.");
        }
        Long boardId = null;
        if (boardSlug != null && !boardSlug.isBlank()) {
            boardId = mapper.findBoardIdBySlug(boardSlug);
            if (boardId == null) {
                return new PostListResponse(List.of(), page, size, 0, 0, false);
            }
        }
        String normalizedTag = tag == null || tag.isBlank() ? null : tag;
        PostSearchCondition condition = new PostSearchCondition(boardId, normalizedTag, authorId, from, to, q);
        LocalDateTime fromAt = from == null ? null : from.atStartOfDay();
        LocalDateTime toExclusive = to == null || to.equals(LocalDate.of(9999, 12, 31))
                ? null : to.plusDays(1).atStartOfDay();
        String qPattern = q == null || q.isBlank() ? null
                : "%" + q.strip().toLowerCase().replace("!", "!!").replace("%", "!%")
                    .replace("_", "!_") + "%";
        long offset = (long) page * size;
        Long viewerId = viewer == null ? null : viewer.id();
        List<PostListRow> rows = mapper.search(condition, viewerId, fromAt, toExclusive, qPattern, size, offset);
        long total = mapper.countSearch(condition, viewerId, fromAt, toExclusive, qPattern);
        Map<Long, List<String>> tags = rows.isEmpty() ? Map.of()
                : mapper.findTagsByPostIds(rows.stream().map(row -> row.id).toList()).stream()
                    .collect(Collectors.groupingBy(PostTagRow::postId,
                            Collectors.mapping(PostTagRow::name, Collectors.toList())));
        List<PostListItemResponse> items = rows.stream()
                .map(row -> toListItem(row, tags.getOrDefault(row.id, List.of()))).toList();
        return new PostListResponse(items, page, size, total,
                (int) ((total + size - 1) / size), offset + rows.size() < total);
    }

    private PostListItemResponse toListItem(PostListRow row, List<String> tags) {
        return new PostListItemResponse(
                row.id,
                row.title,
                row.excerpt,
                new AuthorResponse(row.authorId, row.authorNickname),
                tags,
                row.likeCount,
                row.commentCount,
                row.viewCount,
                row.publishedAt
        );
    }

}

