package org.example.social;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;

@Service
public class RelationService {

    private final MyBatisRelationMapper relationMapper;

    public RelationService(MyBatisRelationMapper relationMapper) {
        this.relationMapper = relationMapper;
    }

    @Transactional(readOnly = true)
    public List<Long> mutuals(Long memberId) {
        return relationMapper.findMutualIds(memberId);
    }

    @Transactional(readOnly = true)
    public List<Long> followBack(Long memberId) {
        return relationMapper.findFollowBackIds(memberId);
    }

    @Transactional(readOnly = true)
    public List<SuggestionResponse> suggestions(Long memberId, int limit) {
        return relationMapper.findSuggestions(memberId, limit).stream()
                .map(r -> new SuggestionResponse(r.getMemberId(), r.getNickname(), r.getMutualCount()))
                .toList();
    }
}

